 static byte[] GroundPixels(double strength,string skin=null){var drawing=new DrawingVisual();using(var d=drawing.RenderOpen())EchoHop.DrawGround(d,1.17,491,3,strength,true,skin);var image=new RenderTargetBitmap(440,510,96,96,PixelFormats.Pbgra32);image.Render(drawing);var pixels=new byte[440*510*4];image.CopyPixels(pixels,440*4,0);return pixels;}
 static int PaletteFloorPixels(byte[] pixels,string skin){int total=0;var color=EchoHop.PaletteForSkin(skin).Main.Color;for(int y=485;y<509;y++)for(int x=0;x<440;x++){int offset=(y*440+x)*4;double alpha=pixels[offset+3]/255.0;if(alpha>.3 && Math.Abs(pixels[offset+2]-color.R*alpha)<3 && Math.Abs(pixels[offset+1]-color.G*alpha)<3 && Math.Abs(pixels[offset]-color.B*alpha)<3)total++;}return total;}
 static int VisiblePixels(byte[] pixels){int count=0;for(int i=3;i<pixels.Length;i+=4)if(pixels[i]>=20)count++;return count;}
 static void CheckEchoBounds(byte[] pixels){for(int y=0;y<510;y++)for(int x=0;x<440;x++)if((x==0 || x==439 || y==0 || y==509) && pixels[(y*440+x)*4+3]>=20)throw new Exception("Echo effect exceeded canvas");}
